#pragma once

// Independent FP64 differentiation of the documented 13-state ideal-Hill
// equations. No generated bytecode or production return-map is evaluated.
#include "cardboard_paper_reference.hpp"

namespace numi_cardboard_solver {
namespace paper = numi_cardboard_paper;
using Jacobian = std::array<double, 169>;

inline std::array<double, 36> hillQuadratic(const paper::Parameters& p) {
    const auto& h = p.hill;
    std::array<double, 36> b{};
    b[0]=h[1]+h[2]; b[7]=h[0]+h[2]; b[14]=h[0]+h[1];
    b[1]=b[6]=-h[2]; b[2]=b[12]=-h[1]; b[8]=b[13]=-h[0];
    b[21]=2*h[3]; b[28]=2*h[4]; b[35]=2*h[5];
    return b;
}

inline std::array<double, 36> elasticNormalized(const paper::Parameters& p) {
    const auto& c=p.c;
    std::array<double,36> a{};
    a[0]=c[0]; a[7]=c[1]; a[14]=c[2];
    a[1]=a[6]=c[3]; a[2]=a[12]=c[4]; a[8]=a[13]=c[5];
    a[21]=2*p.shear[2]; a[28]=2*p.shear[1]; a[35]=2*p.shear[0];
    for(auto& v:a) v/=p.sigmaReference;
    return a;
}

inline Jacobian implicitJacobian(const paper::Parameters& p,
                                 const paper::State& old,
                                 const paper::State& x) {
    const auto b=hillQuadratic(p), c=elasticNormalized(p);
    paper::Vector6 s{}, bs{};
    for(unsigned i=0;i<6;++i) s[i]=x[6+i];
    for(unsigned i=0;i<6;++i) for(unsigned j=0;j<6;++j) bs[i]+=b[6*i+j]*s[j];
    const double q=paper::hillEquivalent(p,s), dl=x[12]-old[12];
    const double gap=1-q;
    const double rho=std::sqrt(dl*dl+gap*gap+p.fischerBurmeisterEpsilon*p.fischerBurmeisterEpsilon);
    if(!(q>0 && rho>0)) throw std::runtime_error("invalid Hill/FB derivative domain");
    Jacobian a{};
    for(unsigned i=0;i<6;++i) {
        const double w=i<3?1:.5;
        a[13*i+i]=1;
        a[13*i+12]=-w*bs[i]/q;
        for(unsigned j=0;j<6;++j) {
            a[13*i+6+j]=-dl*w*(b[6*i+j]/q-bs[i]*bs[j]/(q*q*q));
            a[13*(6+i)+j]=c[6*i+j];
        }
        a[13*(6+i)+6+i]=1;
        a[13*12+6+i]=(1-gap/rho)*bs[i]/q;
    }
    a[13*12+12]=dl/rho-1;
    return a;
}

inline paper::Result project(const paper::Parameters& p, const paper::Matrix& f,
                             const paper::State& old,
                             unsigned limit=64, double tolerance=1e-12) {
    paper::State x=old;
    const auto trial=paper::normalizedSecondPiola(p,f,paper::plasticStrain(old));
    for(unsigned i=0;i<6;++i) x[6+i]=trial[i];
    unsigned iteration=0;
    for(;iteration<limit;++iteration) {
        const auto r=paper::residual(p,f,old,x);
        const double norm=paper::residualNorm(r);
        double scale=1;
        for(double v:x) scale=std::max(scale,1+std::abs(v));
        if(norm<=tolerance*scale) break;
        paper::State rhs{},step{};
        for(unsigned i=0;i<13;++i) rhs[i]=-r[i];
        if(!paper::solveLinear(implicitJacobian(p,old,x),rhs,step))
            throw std::runtime_error("independent analytic local Jacobian singular");
        double alpha=1;
        bool accepted=false;
        for(unsigned bt=0;bt<24;++bt) {
            paper::State next=x;
            for(unsigned i=0;i<13;++i) next[i]+=alpha*step[i];
            const double nn=paper::residualNorm(paper::residual(p,f,old,next));
            if(std::isfinite(nn) && nn<=(1-1e-4*alpha)*norm) {
                x=next; accepted=true; break;
            }
            alpha*=.5;
        }
        if(!accepted) throw std::runtime_error("independent analytic local Armijo failed");
    }
    const double residual=paper::residualNorm(paper::residual(p,f,old,x));
    double scale=1;
    for(double v:x) scale=std::max(scale,1+std::abs(v));
    if(residual>tolerance*scale) throw std::runtime_error("independent analytic projection exhausted");
    const auto ep=paper::plasticStrain(x);
    const auto second=paper::secondPiola(p,f,ep);
    const auto first=paper::multiply(f,second);
    paper::Vector6 s{};
    for(unsigned i=0;i<6;++i) s[i]=x[6+i];
    double work=0;
    const std::array<unsigned,6> idx{0,4,8,5,2,1};
    for(unsigned i=0;i<6;++i) work+=(i<3?1:2)*second[idx[i]]*(x[i]-old[i]);
    return {x,second,first,paper::hillEquivalent(p,s),residual,work,iteration};
}

inline paper::Matrix directionalTangent(const paper::Parameters& p,
        const paper::Matrix& f,const paper::Matrix& h,
        const paper::State& old,const paper::State& projected) {
    const auto ft=paper::transpose(f), ht=paper::transpose(h);
    const auto a=paper::multiply(ft,h), b=paper::multiply(ht,f);
    paper::Matrix de{};
    for(unsigned i=0;i<9;++i) de[i]=.5*(a[i]+b[i]);
    paper::Vector6 strain{de[0],de[4],de[8],de[5],de[2],de[1]};
    const auto c=elasticNormalized(p);
    paper::State rhs{},dx{};
    for(unsigned i=0;i<6;++i) for(unsigned j=0;j<6;++j) rhs[6+i]+=c[6*i+j]*strain[j];
    if(!paper::solveLinear(implicitJacobian(p,old,projected),rhs,dx))
        throw std::runtime_error("independent implicit derivative singular");
    paper::Vector6 ds{};
    for(unsigned i=0;i<6;++i) for(unsigned j=0;j<6;++j)
        ds[i]+=p.sigmaReference*c[6*i+j]*(strain[j]-dx[j]);
    const paper::Matrix dsecond{ds[0],ds[5],ds[4],ds[5],ds[1],ds[3],ds[4],ds[3],ds[2]};
    const auto second=paper::secondPiola(p,f,paper::plasticStrain(projected));
    const auto term1=paper::multiply(h,second), term2=paper::multiply(f,dsecond);
    paper::Matrix result{};
    for(unsigned i=0;i<9;++i) result[i]=term1[i]+term2[i];
    return result;
}

inline paper::Result project(paper::MaterialKind kind,const paper::Matrix& f,
                             const paper::State& old,unsigned limit=64,double tolerance=1e-12) {
    return project(paper::parameters(kind),f,old,limit,tolerance);
}
inline paper::Matrix directionalTangent(paper::MaterialKind kind,
        const paper::Matrix& f,const paper::Matrix& h,
        const paper::State& old,const paper::State& projected) {
    return directionalTangent(paper::parameters(kind),f,h,old,projected);
}
} // namespace numi_cardboard_solver
